public class TracePathLastLifespanColumn : AbstractDynamicTableColumn<PathRow, SpanAndRadix, Trace> {

	record SpanAndRadix(Lifespan span, TimeRadix radix) : Comparable<SpanAndRadix> {
		/* @Override */
		public string toString() {
			return span.toString(radix.format);
		}

		/* @Override */
		public int compareTo(SpanAndRadix that) {
			return this.span.compareTo(that.span);
		}
	}

	private sealed class LastLifespanRenderer : AbstractGColumnRenderer<SpanAndRadix> {
		/* @Override */
		public string getFilterString(SpanAndRadix t, Settings settings) {
			return t == null ? "<null>" : t.toString();
		}

		/* @Override */
		public Component getTableCellRendererComponent(GTableCellRenderingData data) {
			base.getTableCellRendererComponent(data);
			PathRow row = (PathRow) data.getRowObject();
			if (row.isCurrent()) {
				setBold();
			}
			return this;
		}
	}

	private LastLifespanRenderer renderer = new LastLifespanRenderer();

	/* @Override */
	public string getColumnName() {
